arguments.command:
cd /tmp; cat > watch.exp <<'EOF'
set timeout 120
spawn nc 127.0.0.1 9000
expect {
  "login:" { puts "\n=== GOT LOGIN ==="; exit 0 }
  timeout { puts "\n=== TIMEOUT ==="; exit 1 }
}
EOF
expect watch.exp 2>&1 | tail -40

