arguments.command:
cd /tmp; cat > sshtest.exp <<'EOF'
set timeout 40
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=20 -o PreferredAuthentications=password -o PubkeyAuthentication=no root@localhost "echo SSH_LOGIN_OK; id; hostname; cat /etc/alpine-release"
expect {
  "assword:" { send "password123\r"; exp_continue }
  "SSH_LOGIN_OK" { puts "\n>>>LOGIN SUCCESS"; exp_continue }
  "Permission denied" { puts "\n>>>DENIED" }
  eof { }
  timeout { puts "\n>>>TIMEOUT" }
}
EOF
expect sshtest.exp 2>&1 | tail -20

