arguments.command:
cd /tmp; cat > final.exp <<'EOF'
set timeout 40
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost
expect {
  "assword:" { send "password123\r"; exp_continue }
  "# " { send "echo INSIDE_SHELL_OK; uname -a\r"; exp_continue }
  "INSIDE_SHELL_OK" { puts "\n>>>SHELL DROP OK"; send "exit\r" }
  "Permission denied" { puts "\n>>>DENIED"; exit 1 }
  timeout { puts "\n>>>TIMEOUT"; exit 1 }
}
expect eof
EOF
expect final.exp 2>&1 | tail -15

